// src/components/Hero.jsx
import { useEffect, useRef } from "react";
import resume from "../data/resume";
import "./Hero.css";

export default function Hero() {
  const canvasRef = useRef(null);

  // Ambient particle field — restrained: no connecting lines, slow drift
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let animId;
    let W, H, particles;

    const resize = () => {
      W = canvas.width = canvas.offsetWidth;
      H = canvas.height = canvas.offsetHeight;
    };

    const init = () => {
      resize();
      particles = Array.from({ length: 34 }, () => ({
        x: Math.random() * W,
        y: Math.random() * H,
        r: Math.random() * 1.3 + 0.4,
        vx: (Math.random() - 0.5) * 0.12,
        vy: (Math.random() - 0.5) * 0.12,
        alpha: Math.random() * 0.3 + 0.08,
      }));
    };

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      particles.forEach((p) => {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0) p.x = W; if (p.x > W) p.x = 0;
        if (p.y < 0) p.y = H; if (p.y > H) p.y = 0;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(79, 195, 247, ${p.alpha})`;
        ctx.fill();
      });
      animId = requestAnimationFrame(draw);
    };

    init();
    draw();
    window.addEventListener("resize", resize);
    return () => { cancelAnimationFrame(animId); window.removeEventListener("resize", resize); };
  }, []);

  const stats = [
    { value: "1+",    label: "Years Experience" },
    { value: "4+",    label: "Projects Shipped" },
    { value: "99.5%", label: "Uptime Delivered" },
    { value: "3",     label: "Enterprise Clients" },
  ];

  const capabilities = [
    {
      label: "Cross-Platform Apps",
      icon: (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <rect x="5" y="2" width="14" height="20" rx="2" />
          <line x1="12" y1="18" x2="12.01" y2="18" />
        </svg>
      ),
    },
    {
      label: "NetSuite ERP Integration",
      icon: (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M4 17V7a2 2 0 012-2h6l6 6v6a2 2 0 01-2 2H6a2 2 0 01-2-2z" />
          <path d="M12 5v6h6" />
        </svg>
      ),
    },
    {
      label: "Offline-First Architecture",
      icon: (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M12 20a8 8 0 100-16 8 8 0 000 16z" />
          <path d="M12 8v4l3 2" />
        </svg>
      ),
    },
  ];

  return (
    <section id="hero" className="hero">
      <canvas ref={canvasRef} className="hero__canvas" />
      <div className="hero__glow hero__glow--1" />
      <div className="hero__glow hero__glow--2" />

      <div className="hero__inner">
        <div className="hero__content">
          <div className="hero__eyebrow animate-fadeUp" style={{ animationDelay: "0.1s" }}>
            <span className="hero__status-dot" />
            Available for new opportunities
          </div>

          <h1 className="hero__name animate-fadeUp" style={{ animationDelay: "0.2s" }}>
            <span className="hero__name-first">Harsa Vardan</span>
            <span className="hero__name-last"> A K</span>
          </h1>

          <h2 className="hero__title animate-fadeUp" style={{ animationDelay: "0.3s" }}>
            {resume.title}
          </h2>

          <p className="hero__bio animate-fadeUp" style={{ animationDelay: "0.4s" }}>
            I build <span className="hero__highlight">enterprise mobile and desktop applications</span> integrated
            with <span className="hero__highlight">NetSuite ERP</span>, with a focus on
            <span className="hero__highlight"> offline-first architecture</span> and secure,
            production-ready systems.
          </p>

          <div className="hero__actions animate-fadeUp" style={{ animationDelay: "0.5s" }}>
            <a href="#projects" className="btn btn--primary">View My Work</a>
            <a href="#contact" className="btn btn--ghost">Get In Touch</a>
          </div>

          <div className="hero__meta animate-fadeUp" style={{ animationDelay: "0.6s" }}>
            <span className="hero__meta-item">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0116 0z" />
                <circle cx="12" cy="10" r="3" />
              </svg>
              {resume.location}
            </span>
            <span className="hero__meta-sep">·</span>
            <span className="hero__meta-item">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M3 21h18M6 21V8l6-4 6 4v13M10 21v-6h4v6" />
              </svg>
              Bonbloc Technologies
            </span>
          </div>
        </div>

        <div className="hero__right animate-fadeUp" style={{ animationDelay: "0.3s" }}>
          <div className="hero__card">
            <div className="hero__avatar">
              <div className="hero__avatar-ring" />
              <div className="hero__avatar-inner">
                <span className="hero__avatar-initials">HV</span>
              </div>
            </div>

            <ul className="hero__capabilities">
              {capabilities.map((c, i) => (
                <li key={i} className="hero__capability">
                  <span className="hero__capability-icon">{c.icon}</span>
                  {c.label}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      <div className="hero__stats">
        {stats.map((s, i) => (
          <div key={i} className="hero__stat animate-fadeUp" style={{ animationDelay: `${0.6 + i * 0.1}s` }}>
            <span className="hero__stat-value">{s.value}</span>
            <span className="hero__stat-label">{s.label}</span>
          </div>
        ))}
      </div>

      <a href="#about" className="hero__scroll">
        <span className="hero__scroll-line" />
        <span className="hero__scroll-text">Scroll to explore</span>
      </a>
    </section>
  );
}
